(function (all) { var mine = all["uk"] = all["uk"] || {}; var add = {"manual.831d0f72d242":"Початок роботи","manual.f2f53974b760":"Freally Capture — настільна студія для Windows, macOS і Linux. Цей посібник описує версію 1.2.1, поточний випуск.","manual.4b5f10daa08b":"Відкрийте Freally Capture. Під час першого запуску він попросить вас прийняти ліцензійну угоду; потім майстер налаштування перевірить вашу відеокарту й процесор і запропонує кодувальник, розмір полотна й бітрейт, пояснивши причину кожного вибору.","manual.fe88634050bf":"Студія відкривається на попередньому перегляді програми з панелями <strong>Сцени</strong>, <strong>Джерела</strong>, <strong>Мікшер</strong> і <strong>Керування</strong>. Жодного облікового запису й жодного входу.","manual.4c937d2528ca":"У <strong>macOS</strong> дозвольте <strong>Запис екрана</strong> — а також <strong>Камеру</strong> й <strong>Мікрофон</strong>, якщо ви ними користуєтеся, — у «Системні параметри» → «Приватність і безпека», а потім знову відкрийте застосунок. У <strong>Linux з Wayland</strong> власний діалог робочого середовища запитає, який екран чи вікно показати.","manual.adc8f305f8f8":"Додайте перше джерело (див. <a href=\"#build-a-scene\">Створення сцени</a>), і можна записувати чи виходити в ефір.","manual.46e49bd74b1d":"Створення сцени","manual.f779d891c1f2":"Сцена — це стек джерел, скомпонованих на відеокарті. Одне джерело може використовуватися в кількох сценах.","manual.5a1c5f778fdb":"На панелі <strong>Джерела</strong> натисніть <strong>Додати джерело</strong> й виберіть тип: <strong>Дисплей</strong>, <strong>Вікно</strong>, <strong>Гра</strong>, <strong>Вебкамера / карта захоплення</strong>, <strong>Браузер</strong>, <strong>Медіа</strong>, <strong>Зображення</strong>, <strong>Текст</strong>, <strong>Колір</strong> або <strong>Звук</strong>.","manual.2a2d9e2015b5":"Додайте <strong>Захоплення екрана</strong>: попередній перегляд програми заповниться вашим екраном.","manual.80c8e9c8176f":"Додайте джерело <strong>Вебкамера</strong>, перетягніть його в кут полотна й змініть розмір за допомогою маркерів.","manual.264150f36676":"Додайте зверху накладення <strong>Зображення</strong> або <strong>Браузер</strong>. Порядок у списку — це порядок на полотні: верх списку — передній план.","manual.a329c46899d6":"Створіть більше сцен на панелі <strong>Сцени</strong> — наприклад, «Скоро почнемо», «Гра» і «Зараз повернуся» — і перемикайтеся між ними.","manual.9c8d5730d1bb":"<strong>Порада:</strong> змініть властивості спільного джерела один раз — і вони зміняться в кожній сцені, що його використовує.","manual.fd869e76d280":"<strong>Попередній перегляд:</strong> у Windows, macOS і Linux з X11 попередній перегляд програми малюється прямо з відеокарти, тож перетягування, масштабування й обертання відчуваються миттєвими. У Wayland використовується стандартний попередній перегляд із тим самим редагуванням на полотні.","manual.87eca68fecaa":"Фільтри й переходи","manual.36a962cf3902":"Накладайте фільтри на кожне джерело — на відеокарті — і вибирайте, як одна сцена поступається місцем наступній.","manual.4708b4dbab34":"Додайте хромакей","manual.9df34cebcaf5":"Клацніть правою кнопкою джерело — скажімо, камеру із зеленим екраном — і виберіть <strong>Фільтри</strong>.","manual.9981601a6174":"Додайте <strong>Хромакей</strong> і налаштуйте <strong>Ключовий колір</strong>, <strong>Схожість</strong>, <strong>Плавність</strong> і <strong>Розтікання</strong>: вирізаний колір зникає з полотна наживо.","manual.b76bd309a9f6":"Додавайте інші фільтри за потреби — <strong>Корекція кольору</strong>, <strong>LUT</strong>, <strong>Розмиття</strong>, <strong>Маска</strong>, <strong>Різкість</strong> — і перетягуйте їх, щоб змінити порядок у ланцюжку.","manual.db41fe5a40e4":"Задайте перехід","manual.bea9e11be98d":"На панелі <strong>Керування</strong> відкрийте вибір переходу, виберіть <strong>Зріз</strong>, <strong>Згасання</strong>, <strong>Зсув</strong>, <strong>Змахування</strong>, <strong>Стингер</strong> або <strong>Люма-шторка</strong> й задайте тривалість.","manual.eada58ce5b2e":"Для <strong>Стингера</strong> виберіть медіафайл і точку переходу; для <strong>Люма-шторки</strong> — градієнт і його м'якість.","manual.79756cb8b209":"Перемкніть сцени, щоб побачити, як відтворюється перехід. У режимі студії він відтворюється, коли ви надсилаєте попередній перегляд у програму.","manual.2c0c025b4264":"Компонувальник і візуальні ефекти","manual.b768e85eff32":"3D-нахил, вихідні кеї, стоп-кадр і клонування, сімейство розмиттів, переходи з рухом і правилами, студія шейдерів, маски Безьє та стингери з трек-маттом.","manual.d2b720eca5a5":"3D-нахил і перспектива","manual.d665cc2f2296":"Відкрийте <strong>Змінити трансформацію</strong> для елемента й задайте <strong>Нахил X</strong>, <strong>Нахил Y</strong> і силу ефекту <strong>Перспектива</strong>, щоб закріпити джерело в 3D. Трансформація без нахилу рендериться точно так само, як і раніше.","manual.c4077ba2b72d":"Вихідні кеї","manual.d4220af54ed9":"Відкрийте <strong>Інструменти → Вихідні кеї</strong> й додайте будь-яке джерело як шар поверх <strong>виводу програми</strong> — над кожною сценою й крізь кожну зміну сцени: логотип каналу, значок LIVE, нижній титр.","manual.0677e571c1f8":"Змінюйте порядок шарів і задавайте для кожного непрозорість, положення, розмір і стан «увімкнено/вимкнено». Вони однаково з'являються в попередньому перегляді, записі, трансляції та мультив'ю.","manual.1e484119e149":"Стоп-кадр і клонування джерел","manual.4cdb8e22f58b":"Клацніть правою кнопкою джерело, відкрийте <strong>Фільтри</strong> й додайте <strong>Заморозити</strong>: фільтр утримує останній кадр одночасно в програмі, попередньому перегляді, записі й трансляції. Вимкніть його, щоб розморозити.","manual.59fd957b48dc":"Натисніть кнопку <strong>Клонувати</strong> (⧉) у рядку джерела, щоб розмістити один сигнал у кількох сценах чи місцях, кожен клон — із власною трансформацією й фільтрами.","manual.a90410d6b30c":"Розмиття","manual.eeb69e428aa3":"У <strong>Фільтрах</strong> джерела додайте одне з розмиттів, окрім гаусового: <strong>Спрямоване</strong> (смуга руху під кутом), <strong>Радіальне</strong> (обертання навколо центру), <strong>Зум</strong> (смуга наїзду камери) або <strong>Пікселізація</strong> (мозаїка).","manual.54261c9f6b8f":"Перехід переміщення й правила переходів","manual.ef17a04962be":"Виберіть перехід <strong>Переміщення</strong>: елементи, що є в обох сценах, плавно перетікають зі старих положення, масштабу, обертання й обрізання в нові замість різкої зміни, а елементи, що є лише в одній сцені, плавно з'являються чи зникають.","manual.e31792f9e737":"Відкрийте <strong>Інструменти → Правила переходів</strong>, щоб задати парі сцен власний перехід і тривалість. Для власної появи елемента задайте плавну появу <strong>Проявлення</strong> в <strong>Змінити трансформацію</strong>.","manual.bb4e30a1ea68":"Студія шейдерів WGSL","manual.e475acf03bea":"Додайте <strong>користувацький ефект WGSL</strong> як фільтр і редагуйте його наживо. Його повзунки створюються з анотацій <code>// @param</code>, а вбудована галерея містить відтінки сірого, інверсію, рядки розгортки й віньєтку.","manual.424ca3316822":"<strong>Порада:</strong> шейдер компілюється й перевіряється під час введення. Некоректний шейдер ігнорується, і джерело рендериться без фільтра — без жодного збою.","manual.c24e8b5ee2c0":"Маски Безьє","manual.37870edaacbc":"Додайте фільтр <strong>маска довільної форми</strong> й намалюйте замкнений контур: перетягуйте маркери, двічі клацніть, щоб додати точку, клацніть правою кнопкою, щоб видалити. Є готові форми, розмиття для кожного краю окремо й інверсія.","manual.f44ad1306530":"Експортуйте будь-який контур як шаблон <strong>люма-шторки</strong> у відтінках сірого, щоб використати форму як перехід.","manual.e4c8b0c52b3e":"Стингери з трек-маттом","manual.b35494db6ce6":"Налаштуйте стингер так, щоб він ніс свою прозорість як <strong>трек-матт</strong>, із заливкою й маттом <strong>Поруч</strong> або <strong>Один над одним</strong>, — тож прозорість переживає кодеки, які її відкидають (H.264 і HEVC). За бажання <strong>приглушуйте звук програми</strong> під власним звуком стингера, поки він відтворюється.","manual.3879f0c73d18":"Накладення та інші джерела","manual.cea21c089e39":"Повтор, плейлисти, титри, індикатори, накладення статистики, таймери, накладення введення й два мережеві сигнали — усе з меню <strong>+ / Додати джерело</strong> на панелі <strong>Джерела</strong>.","manual.4a459b922e4b":"Миттєвий повтор","manual.2e042aa67065":"Спершу ввімкніть буфер повторів (<strong>Увімкнути повтор</strong> на панелі <strong>Керування</strong>), потім виберіть <strong>Миттєвий повтор</strong> у <strong>+ / Додати джерело</strong> й розмістіть його в сцені.","manual.d7645da473a6":"Виводьте останні секунди в програму гарячою клавішею повтору — їх скопійовано без перекодування й відтворено на швидкості <strong>100%</strong>, <strong>50%</strong> або <strong>25%</strong>, сповільнено, а не з вигаданими кадрами. Під час відтворення можна перемотувати чи ставити на паузу.","manual.5b8095e70de0":"Наприкінці джерело очищується саме, тож ефір сам повертається до живого сигналу.","manual.6433eaab9b10":"<strong>Порада:</strong> сповільнений повтор навмисно беззвучний: сповільнений звук розмазувався б, тож його краще прибрати, ніж підробляти.","manual.f0b63d46cd74":"Медіаплейлист і фонова музика","manual.37ed12f9d130":"Додайте <strong>Медіаплейлист (без пауз)</strong> і складіть упорядкований список із точками входу й виходу та точками сигналу для кожного елемента. Увесь список відтворюється через один декодер, тож стики точні до кадру й справді без пауз.","manual.ef41fa6ad9b5":"Виберіть, як він відтворюється, — <strong>Цикл</strong>, <strong>Перемішати</strong> чи <strong>Утримувати останній</strong>, — і переходьте списком гарячими клавішами «наступний» і «попередній». Плейлист лише зі звуком показує на полотні <strong>назву поточного треку</strong> й відтворюється через власну смугу мікшера; натисніть кнопку <strong>Моніторинг</strong> на цій смузі, щоб його почути.","manual.6e641ae2bd92":"Для музики, яка грає без нічого на екрані, натомість виберіть <strong>+ / Додати джерело → Фонова музика…</strong> і виберіть один чи кілька файлів <code>.mp3</code>, <code>.wav</code> або <code>.flac</code>, за бажання — у випадковому порядку. Вона вимикає власний звук відеофону, тож чути завжди щось одне.","manual.b9aad55133bf":"Конструктор титрів і табло","manual.5382c093aaef":"Додайте <strong>Титр / табло</strong>, щоб відкрити конструктор: накладайте шари <strong>Текст</strong>, <strong>Зображення</strong> і <strong>Форма</strong>, з текстом з обведенням і тінню та анімаціями появи й зникнення (згасання, зсув, шторка).","manual.7b8fea70655a":"Прив'яжіть поля до відстежуваного файлу (клітинки CSV чи вказівника JSON) або до змінної студії, а потім керуйте наживо: змініть ім'я, відредагуйте рахунок чи запустіть анімацію, не торкаючись сцени.","manual.88a9422e37a9":"Аудіовізуалізатор","manual.87f4a5bdd624":"Додайте <strong>Аудіовізуалізатор</strong> і виберіть стиль — <strong>Смуги спектра</strong>, <strong>Осцилограф</strong> або стерео <strong>VU-індикатори</strong>, — а потім прив'яжіть його до будь-якої смуги мікшера, доріжки чи майстер-міксу. Він показує й звук відеофону.","manual.0ae90a461adb":"У <strong>Властивостях</strong> джерела ввімкніть <strong>Класичні кольори</strong> для зеленої, жовтої й червоної зон або залиште їх вимкненими для одного суцільного кольору. Там же — розмір, кількість смуг і швидкість спадання.","manual.0d1ceffb08ba":"<strong>Порада:</strong> візуалізатор слухає <strong>після фейдера</strong>, тож заглушене джерело показує пряму лінію: він показує саме те, що ви чуєте.","manual.ec642e1cf0cc":"Накладення статистики, таймер сплітів і накладення введення","manual.6b4fe6f81cb0":"Додайте <strong>Статистика продуктивності (HUD)</strong>, щоб показати на полотні виміряні числа з панелі статистики — кадри за секунду, CPU, пам'ять, час компонування на GPU, пропущені кадри й поточний бітрейт; кожен рядок можна ввімкнути чи вимкнути. Завантаження GPU навмисно не показується, бо його не вимірюють.","manual.cbd8a4b88736":"Додайте <strong>Спідран-таймер сплітів</strong>, імпортуйте файл LiveSplit <code>.lss</code> і керуйте ним глобальними гарячими клавішами спліту, скасування, пропуску й скидання, порівнюючи з особистим рекордом, найкращими сегментами чи середнім. Файл лише читається; забіг ніколи не записується назад.","manual.fbf4bbeaf903":"Додайте <strong>Накладення введення (клавіші/геймпад)</strong>, щоб показувати клавіатуру, мишу й геймпад наживо в одній із чотирьох розкладок (WASD, компактна клавіатура, геймпад із двома стіками, 8-напрямний файтинг-стік). Клавіатура й миша працюють у Windows; геймпади — в усіх трьох системах.","manual.bf794edb3c25":"Панель соцмереж і каналів","manual.5f898056ef11":"Додайте <strong>Панель соцмереж</strong> із <strong>+ / Додати джерело</strong>: панель зі списком ваших імен користувача. Для кожного рядка виберіть платформу — <strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong> як кольорові значки або <strong>Власний</strong> із власним підписом і кольором — і введіть ім'я (наприклад, <code>@mychannel</code>). Додайте необов'язковий рядок заголовка («Підписуйтеся»), змініть порядок рядків і задайте розмір і кольори тексту.","manual.1dab9389547a":"Кожне поле можна змінити у <strong>Властивостях</strong> джерела. Рядки без імені пропускаються, тож можна тримати повний список і заповнювати лише те, чим ви користуєтеся.","manual.1a4ac3c2e0bf":"Вибране повідомлення чату","manual.c5d58a7d58be":"Відкрийте <strong>Інструменти → Вибране повідомлення чату…</strong> (або палітру команд). Там перелічено найновіші рядки з кожного запущеного накладення чату: натисніть <strong>Закріпити</strong> біля одного з них, щоб закріпити його в програмі як банер, який бачать глядачі трансляції й запису.","manual.162d364796a2":"Задайте в діалозі кольори <strong>банера</strong> й <strong>тексту</strong> та натисніть <strong>Прибрати</strong>, щоб зняти його з ефіру. Саме закріплення знімається під час перезапуску — так задумано: вчорашнє привітання ніколи не переслідує сьогоднішній ефір.","manual.89a84c53e014":"Підсвічування курсора й ефекти клацань","manual.d0a5d9fb047d":"Клацніть правою кнопкою захоплення дисплея чи вікна, відкрийте <strong>Фільтри</strong> й додайте <strong>Ефекти курсора</strong>: <strong>Ореол курсора</strong> (колір і радіус), <strong>Хвилі від клацань</strong> різних кольорів для лівої й правої кнопок і необов'язковий <strong>Показ клавіш</strong> поряд із вказівником. Зміни видно наживо.","manual.4a17c44757e4":"<strong>Примітка:</strong> ефекти курсора працюють лише у Windows; macOS і Linux малюють курсор самі. Накладення введення й показ клавіш зчитують введення <strong>лише тоді, коли вони ввімкнені</strong>, і малюють його прямо в зображення: нічого не зберігається й не журналюється.","manual.8bdb1aadf964":"Мережеві джерела: приймання з локальної мережі та Freally Link","manual.797fe86a1fe8":"Додайте <strong>Приймання з LAN (слухач SRT/RTMP)</strong>, щоб відкрити слухача на цьому комп'ютері, а потім спрямуйте застосунок камери на телефоні, кодувальник або другий комп'ютер на показану адресу (з QR-кодом). Сигнал з'явиться в сцені з власною смугою мікшера. SRT може передавати необов'язкову парольну фразу AES; RTMP не має власної автентифікації, тож форма надає перевагу SRT.","manual.e2761818ccef":"Щоб обмінюватися сигналом між двома копіями Freally Capture, увімкніть вихід <strong>Freally Link</strong> на комп'ютері, що <strong>надсилає</strong>, і задайте його <strong>Ключ сполучення</strong> — без нього вихід не ввімкнеться. На комп'ютері, що <strong>приймає</strong>, додайте <strong>Freally Link (інший екземпляр)</strong>, натисніть <strong>Сканувати LAN</strong> і введіть ключ: програма відправника з'явиться як джерело. Жодній стороні не потрібен ffmpeg, а приймач без ключа ніколи не побачить жодного кадру.","manual.a793cb271e32":"<strong>Примітка:</strong> обидва мережеві джерела <strong>вимкнені, доки ви їх не додасте</strong>, лишаються у вашій власній мережі й ніколи не торкаються інтернету: ніщо вас не знаходить і ніщо не з'єднується назовні.","manual.de10be5dcf2c":"Зворотний відлік «Скоро почнемо»","manual.71b47ef78ea4":"Екран очікування перед ефіром одним клацанням: великий зворотний відлік до початку шоу поверх зображення, GIF, відео, градієнта чи музики, що блимає на нулі й чекає, поки ви перемкнетеся на шоу.","manual.303493002776":"Додайте зворотний відлік","manual.f78f2994b5d5":"На панелі <strong>Джерела</strong> відкрийте <strong>+ / Додати джерело</strong> й виберіть <strong>Скоро почнемо…</strong>. Джерело розміщує на сцені зворотний відлік на все полотно — підпис над великим числом.","manual.c4bff5a4f06e":"Введіть <strong>підпис</strong> («Скоро почнемо», «Зараз повернуся»), потім задайте час за допомогою <strong>вибору часу</strong>: <strong>година</strong> (1–12), <strong>хвилина</strong> з кроком п'ять хвилин і <strong>AM</strong> або <strong>PM</strong>. Джерело відлічує час до цієї пори доби.","manual.59b00df516f1":"На нулі зворотний відлік <strong>блимає й зупиняється на 0:00:00</strong> — він ніколи сам не перемикає сцени. Перемкніться на сцену ефіру, коли будете готові. Кожне поле можна змінити у <strong>Властивостях</strong> джерела.","manual.1dfb2d817d39":"Виберіть фон","manual.edc2450aeecd":"Виберіть заливку: двоколірний <strong>Градієнт</strong> (за замовчуванням), <strong>Суцільний</strong> колір, <strong>Зображення</strong> (натисніть <strong>Огляд…</strong>) або <strong>Прозорий</strong>, щоб крізь нього було видно джерело під ним.","manual.07a5fd9ac032":"Виберіть файл <strong>GIF</strong> або <strong>відео</strong>, і він крутитиметься в циклі позаду чисел, <strong>масштабований за розміром і відцентрований</strong>, тож видно все зображення й нічого не обрізано.","manual.1cda5be75376":"Додайте <strong>фонову музику</strong> кнопкою <strong>Огляд…</strong> у діалозі (MP3, WAV, FLAC, M4A, AAC, OGG або Opus). Вона відтворюється в циклі, ви чуєте її в попередньому перегляді, і вона входить у запис і трансляцію. Власний звук відеофону вимикається, тож чути завжди щось одне.","manual.b39b6b7add20":"<strong>Порада:</strong> для музики за простим екраном залиште фон «Градієнт» або «Прозорий» і додайте музику: охайний зворотний відлік зі звуковим супроводом.","manual.84f506f4fca5":"Звуковий мікшер","manual.480e299c8728":"Зводьте кожне звукове джерело, надсилайте його на будь-яку з 6 доріжок і очищуйте звук мікрофона — усе наживо.","manual.bcbc220b3e63":"Кожне звукове джерело — це смуга в <strong>Мікшері</strong>: назва, індикатор рівня, фейдер, кнопки вимкнення звуку й моніторингу, фільтри й точки доріжок (1–6).","manual.03b920dc5376":"Перетягніть фейдер, щоб задати рівень, натисніть <strong>Заглушити</strong> або <strong>Моніторинг</strong> і надішліть джерело на будь-яку з 6 доріжок.","manual.9a9991c7dc36":"Відкрийте <strong>фільтри</strong> джерела й додайте <strong>Шумозаглушення</strong> (класична обробка сигналу, без ШІ), <strong>Шумовий гейт</strong>, <strong>Компресор</strong>, <strong>Лімітер</strong>, <strong>Еквалайзер</strong> або <strong>Підсилення</strong>.","manual.1a58b91bc5aa":"Призначте гарячу клавішу <strong>Push-to-talk</strong> чи <strong>Push-to-mute</strong> і стежте за індикатором <strong>LUFS</strong>, щоб контролювати гучність програми.","manual.7158a36ed4d5":"<strong>Примітка для macOS:</strong> macOS сама по собі не дає застосункам доступу до «того, що ви чуєте». Використовуйте звук ScreenCaptureKit (macOS 13 або новіша), де він доступний, або встановіть віртуальний пристрій, як-от BlackHole, і виберіть його як джерело системного звуку. Freally Capture підкаже вам і продовжить запис, навіть якщо одне джерело не вдається відкрити.","manual.bfdd510698ef":"Запис","manual.e39b756fce99":"Записуйте програму на кілька доріжок апаратним кодувальником відеокарти або без втрат у власному форматі Capture.","manual.ad438c2dbf4b":"У <strong>Налаштування → Вивід</strong> виберіть кодувальник. Freally Capture знаходить <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> або <strong>VideoToolbox</strong> і вибирає найкращий; <strong>x264</strong> на процесорі завжди доступний як запасний варіант.","manual.3bc1870f8449":"Виберіть контейнер — <strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> або <strong>WebM</strong> — або власний формат Capture без втрат <strong>freally-video</strong> (<code>.frec</code>), якому не потрібно нічого додатково встановлювати.","manual.e2a332927058":"Надсилайте джерела на звукові доріжки (до 6), щоб мікрофон, системний звук і ваші гості лишалися окремими для монтажу. За бажання ввімкніть <strong>поділ файлів</strong> і <strong>локальну копію з окремими доріжками під час трансляції</strong>.","manual.e0fa2f5a9430":"Натисніть <strong>Почати запис</strong> на панелі <strong>Керування</strong>. Зелена точка <strong>REC</strong> показує час і кількість доріжок. Натисніть <strong>Зупинити</strong>, щоб завершити файл.","manual.b1eb969490f1":"<strong>Примітка щодо кодеків:</strong> MP4 з H.264 і AAC (а також HEVC чи AV1) використовує запатентовані кодеки, які надає <strong>ffmpeg</strong>, що <em>не постачається в комплекті</em>: Freally Capture завантажує його, коли він уперше знадобиться, і перевіряє. Формату без втрат <strong>freally-video</strong> нічого завантажувати не потрібно.","manual.691bff5377a8":"Запис і повтори вглиб","manual.3c2d08430816":"Усе навколо файлу: окремі записи кожного джерела, обрізання кліпів, справжня прозорість, поділ і мітки за подіями, завдання після запису, перевірка цілісності й таймкод SMPTE. Усе це вимкнено, доки ви не ввімкнете, і ніщо з цього не виходить у мережу.","manual.537ffa2b9063":"ISO-запис кожного джерела","manual.e57aa725fa41":"Відкрийте <strong>Налаштування → Вивід</strong> і знайдіть <strong>ISO-запис</strong>. Увімкніть <strong>Записувати «{name}» як окремий ISO-файл</strong> для кожного джерела, яке ви хочете мати чистим: кожне записується до компонування, з розміром полотна й частотою кадрів, тож кожен файл збігається з програмою на часовій шкалі монтажу. Кожен віддалений гість — це джерело, тож кожен гість теж отримує файл.","manual.4bce8f25ec9c":"Залиште <strong>Записувати з фільтрами джерела</strong> позначеним для обробленого вигляду або зніміть позначку для сирого джерела, і виберіть для кожного запису <strong>Формат ISO</strong> та <strong>Відеокодувальник ISO</strong>. Звук береться після фільтрів, але до фейдера й вимкнення звуку, тож рішення під час зведення ніколи не заглушить ISO-файл.","manual.7f29ae4e2c55":"<strong>Порада:</strong> два ISO-записи комфортно тягне відеокарта середнього рівня; кожен наступний коштує ще одного рендерингу й кодування, і панель про це каже.","manual.b2aad668b8b9":"Обрізання повторів і кліпів","manual.c8af16e1cd4f":"Відкрийте збережений запис у вікні <strong>Обрізати</strong> зі списку записів, переходьте по кадрах кнопками <strong>Кадр назад</strong> і <strong>Кадр уперед</strong> і задавайте точки кнопками <strong>Точка входу</strong> й <strong>Точка виходу</strong>, спостерігаючи за відео.","manual.1f80dfd03a36":"Перевірте значок перед експортом. Зелений <em>«Експорт без перекодування»</em> означає, що точка входу припадає на ключовий кадр (майже миттєво й без втрат); бурштиновий значок попереджає, що буде перекодування, — натисніть <strong>Ключовий кадр</strong>, щоб прив'язати точку входу для різання без втрат. Натисніть <strong>Експортувати кліп</strong> або <strong>9:16</strong>, щоб експортувати вертикальну версію.","manual.8a92b0b480f4":"Запис із прозорістю","manual.79bfd450e6aa":"У <strong>Налаштування → Вивід</strong> увімкніть <strong>Записувати з прозорістю (альфа)</strong>, щоб записувати програму на прозорому фоні у формат Capture <code>.frec</code>. Запис отримує власний прозорий рендер, тож ваші попередній перегляд і трансляція зберігають звичайне зображення. Зі списку записів експортуйте <code>.mov</code> у <strong>ProRes 4444</strong> або <strong>QuickTime Animation (QTRLE)</strong> для свого відеоредактора; MP4 і MKV сплющують прозорість.","manual.fade0a9d0454":"<strong>Примітка:</strong> прозорість — це лише прапорець у заголовку <code>.frec</code>, тож ці файли відтворюються всюди, де відтворюється <code>.frec</code>, а старіші файли відкриваються як непрозорі.","manual.33e5c9a96c5d":"Поділ і автоматичні мітки","manual.5596d47693a3":"У налаштуваннях поділу для <code>.frec</code> виберіть, щоб новий файл починався при <strong>зміні сцени</strong>, <strong>маркері</strong> або <strong>кроці сценарію</strong>. Кожна частина починається точно з кадру цієї події й триває щонайменше секунду, тож потік подій не створить купу крихітних файлів.","manual.7fc20a49c196":"Увімкніть <strong>Автоматично ставити мітки розділів на події студії</strong>, щоб позначати як розділи зміни сцен, збережені повтори, перепідключення, сплески пропущених кадрів, тривоги й дії правил. Вони потрапляють у назви розділів MKV і у файл <code>.chapters.txt</code> поруч із записом — разом із мітками, які ви ставите гарячою клавішею.","manual.519fceb746f3":"Після запису: конвеєр і перевірка цілісності","manual.561bb55d7a18":"Зберіть <strong>Конвеєр після запису</strong> для кожного профілю з фіксованого набору кроків — <strong>Перевірити</strong>, <strong>Перепакувати в MP4</strong>, <strong>Нормалізувати гучність</strong>, <strong>Перейменувати</strong>, <strong>Перемістити до теки</strong>, <strong>Скопіювати до теки</strong>, <strong>Показати у файловому менеджері</strong> і <strong>Сповістити Lua-скрипти</strong>. Він працює у фоні з живою чергою й зупиняється на першій невдачі. Кроку «виконати будь-яку команду» навмисно немає.","manual.2f93cddd1f21":"Запускайте перевірку цілісності після запису або будь-коли, щоб отримати простий результат «OK», «попередження» чи «невдача» для пунктів <strong>Контейнер</strong>, <strong>Безперервність відео</strong>, <strong>Безперервність аудіо</strong>, <strong>Чергування аудіо й відео</strong> і <strong>Тривалість</strong>. Файли <code>.frec</code> проходять глибоку перевірку; інші файли — перевірку структури й декодування через ffmpeg.","manual.0d291aee5546":"Експорт копії для поширення після зупинки","manual.124d2a00ed27":"У <strong>Налаштування → Вивід</strong>, коли вибрано контейнер <code>.frec</code>, позначте <strong>Також зберігати MP4 для поширення поруч із майстром</strong>. Коли запис завершується, фоновий експорт записує поруч із майстер-файлом без втрат <code>.mp4</code>, який може відтворити будь-хто.","manual.a37303723389":"Копія з'являється в черзі після запису, отримує ім'я, що ніколи нічого не перезаписує, і ніколи не торкається майстер-файлу. Вона вимкнена, доки ви її не ввімкнете.","manual.7ed8656eb1ff":"Таймкод SMPTE LTC","manual.3d97874c3064":"Відкрийте <strong>Таймкод SMPTE (LTC)</strong>, увімкніть <strong>Генерувати LTC на доріжку</strong> й виберіть доріжку мікшера та частоту кадрів, щоб живити зовнішні рекордери й камери. Задайте в <strong>Читати LTC з</strong> аудіовхід, щоб показувати рядок таймкоду в накладенні статистики й ставити мітки розділів LTC. Класичний звуковий таймкод, повністю офлайн, з точністю до одного кадру на 24, 25 і 30 fps.","manual.a9f690169703":"Вихід в ефір","manual.8f6df4580812":"Транслюйте прямо зі свого комп'ютера на платформу через RTMP чи RTMPS — ніколи не через наш сервер.","manual.dba22b61cdcc":"Відкрийте <strong>Налаштування → Трансляція</strong> й натисніть <strong>Додати напрямок</strong>. Виберіть <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> або <strong>Власний RTMP</strong>.","manual.2192731aac47":"Вставте свій <strong>ключ трансляції</strong> — він зберігається на вашому комп'ютері й відображається замаскованим — і задайте бітрейт і кодувальник для цього сервісу.","manual.040014e94f16":"Натисніть <strong>В ефір</strong> на панелі <strong>Керування</strong>. Засвітиться індикатор <strong>В ефірі</strong>, а панель статистики покаже ваш бітрейт, пропущені кадри й стан трансляції.","manual.0cd441959cb4":"Якщо з'єднання обривається, Freally Capture <strong>перепідключається сам</strong>, а ваш локальний запис триває незалежно від того, що відбувається з трансляцією. За бажання задайте <strong>затримку трансляції</strong>.","manual.dc8ebcea4893":"Натисніть <strong>Завершити трансляцію</strong>, щоб зупинити.","manual.973adc03e43c":"Безпека ефіру","manual.53fa9293a65e":"Як не втратити ефір — до, під час і після.","manual.de8792b14216":"До: перевірка перед виходом в ефір","manual.ed9a4b7bfaf5":"Натискання <strong>В ефір</strong> спершу запускає контрольний список: напрямки трансляції мають ключі, придатний кодувальник знайдено, кожне джерело справне й на диску досить місця для запису — кожен пункт зелений чи червоний, з виправленням в одне клацання, — а також нагадування про рівні мікрофона й звуку робочого столу та про буфер повторів, які ніколи не блокують ефір лише з екраном. Налаштування може <strong>утримувати «В ефір», доки кожна блокувальна перевірка не стане зеленою</strong>; інакше доступна кнопка «Усе одно в ефір».","manual.9b63c5c64ba1":"Під час: тривоги, стан і перемикання","manual.9c386b745073":"<strong>Тривоги безпеки</strong> стежать, поки ви в ефірі чи записуєте: тиша у звуці програми, тривале перевантаження, чорне чи застигле зображення й <em>прогноз</em> браку місця на диску («приблизно 22 хвилини лишилося за поточного бітрейту»). Вони з'являються як банер, який можна закрити, і програми зчитування з екрана їх оголошують — це ніколи не діалог, що перериває ефір.","manual.b7c8c66a5330":"<strong>Панель стану джерел</strong> (палітра команд → «Стан джерел…») показує стан кожного джерела, частоту кадрів, вік останнього кадру, пропущені кадри й перезапуски, з кнопками <strong>Перезапустити</strong> й <strong>Властивості</strong> для кожного.","manual.92bd60ef963b":"Якщо апаратний кодувальник дає збій посеред трансляції чи запису — скидання драйвера, перевантаження відеокарти, — <strong>перемикання кодувальника</strong> переходить на інший апаратний кодувальник або на x264. Трансляція перепідключається й триває, запис продовжується в новому файлі, а повідомлення точно каже, що сталося. Мережеві проблеми ніколи не спричиняють перемикання.","manual.50a02fe4fe7b":"<strong>Тривожна кнопка</strong> (глобальна гаряча клавіша на ваш вибір) перемикає програму — а також вертикальне полотно й будь-які проєктори — на заставку приватності, зупиняє кожне захоплення й вимикає весь звук, зокрема мікрофон, поки трансляція й запис лишаються підключеними. Повернення вимагає навмисного двокрокового підтвердження. Колір чи зображення заставки задаються поряд із гарячою клавішею в <strong>Налаштування → Гарячі клавіші</strong>.","manual.a73a2857361e":"Після: безпечні записи й упорядкований вихід","manual.bf07b060e7e7":"Записи MP4 і MOV пишуться <strong>фрагментами</strong>, тож збій чи вимкнення живлення все одно лишає файл, який можна відтворити (MKV і <code>.frec</code> уже були такими). Якщо сесія обривається посеред запису, наступний запуск пропонує в одне клацання <strong>Відновити</strong> його в копію <code>(repaired)</code>; оригінал ніколи не змінюється.","manual.da5eeb31c1b8":"Вихід із застосунку під час ефіру, запису чи з увімкненим повтором показує, що станеться, а потім завершує все <strong>по черзі</strong>: завершує трансляцію, фіналізує запис, зберігає буфер повторів, зберігає вашу роботу.","manual.26b3f2c32e05":"<strong>Імена файлів записів</strong> формуються за шаблоном (<strong>Налаштування → Вивід</strong>) із токенів — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — для записів, повторів і стоп-кадрів, з окремими теками для повторів і стоп-кадрів.","manual.27c3f23547ac":"<strong>Експорт діагностики</strong> зберігає набір технічних даних у файл на вашому комп'ютері, зібраний за суворим списком дозволених, тож ключів трансляції, паролів, шляхів до файлів та імен у ньому ніколи немає. Ви можете спершу прочитати вміст; він лишається там, де ви його зберегли, і нікуди не надсилається.","manual.5199babf9b90":"Джерела та пристрої","manual.306121fdda68":"Усе між об'єктивом і полотном: тестові сигнали, калібрування синхронізації, текст із файлу, таймери, мапа гарячих клавіш, мікшер вглиб і справжнє керування пристроями.","manual.5eacf1ee941f":"Тестові сигнали й калібрування синхронізації звуку й відео","manual.920b7abd63cc":"Додайте джерело <strong>Тестовий сигнал</strong> (<strong>Джерела → + → Тестовий сигнал</strong>): кольорові смуги, калібрувальна сітка, рухома розгортка, налаштувальний тон 1 kHz на −20 dBFS або комбінований <strong>спалах і сигнал</strong> для синхронізації звуку й відео — зображення й звук від одного годинника. Перевіряйте проєктор, кодувальник чи напрямок трансляції без під'єднаної камери.","manual.788073298328":"Відкрийте стенд <strong>калібрування синхронізації звуку й відео</strong> (палітра команд → «Калібрування синхронізації звуку й відео…»). Виберіть камеру й мікрофон для вирівнювання, наведіть камеру на програму, що блимає (діалог може відкрити для цього повноекранний проєктор), і дайте йому міряти близько дванадцяти секунд. Він знаходить спалах і сигнал за кілька циклів і пропонує застосувати виміряний зсув до мікрофона; ручний повзунок лишається запасним варіантом. Вимірювання проходить через ваш екран і динаміки, тож їхні власні невеликі затримки входять у нього, — а в разі невдачі інструмент каже, <em>чому</em>.","manual.825c83c405fb":"Таймери, годинники й текст із файлу","manual.85622b429b51":"Джерело <strong>Таймер</strong> показує годинник (у вашому власному форматі й з необов'язковим фіксованим зсувом UTC), <strong>Зворотний відлік</strong> (на певну тривалість або до наступного моменту доби — на нулі він може блимнути чи змінити сцену), <strong>Секундомір</strong> або <strong>час від виходу в ефір чи початку запису</strong>. Запускайте, ставте на паузу й скидайте його з <strong>Властивостей</strong> або призначте дві глобальні гарячі клавіші, що керують <em>усіма</em> таймерами одночасно (<strong>Налаштування → Гарячі клавіші</strong>).","manual.fcd4f802968f":"Джерело <strong>Текст</strong> може <strong>читати з відстежуваного файлу</strong> (<strong>Властивості → Читати з файлу</strong>): увесь файл <code>.txt</code>, одну клітинку CSV (за назвою чи номером стовпця) або одне значення JSON (вказівник на кшталт <code>/teams/0/score</code>). Зміни з'являються протягом пів секунди. Табло й нижні титри без жодного сервісу за ними.","manual.1d106549f0ce":"Мапа гарячих клавіш і мікшерний пульт","manual.5d6ad89f147c":"<strong>Мапа гарячих клавіш</strong> (палітра команд → «Мапа гарячих клавіш…») показує <em>кожну</em> прив'язку — глобальні дії та push-to-talk і push-to-mute кожного джерела — з пошуком і фільтрами й чесно позначає конфлікти: та сама комбінація, записана двома способами, показується як спільна, а клавіша, яку система відмовилася зареєструвати (бо нею володіє інший застосунок), про це каже. <strong>Експортувати шпаргалку</strong> записує довідку Markdown до вашої теки «Завантаження».","manual.e32e382b9753":"Кожна смуга мікшера має <strong>Панораму</strong> (стереобаланс; центр — це рівно відсутність панорамування, а подвійне клацання її скидає), <strong>Соло PFL</strong> (моніторинг чує лише смуги в режимі соло; мікс програми ніколи не змінюється) і <strong>Моно</strong>-зведення. Панорама й моно — в меню «⋯» смуги; соло — на самій смузі.","manual.5dbd70dfc92d":"Пристрої вглиб: деінтерлейсинг і керування камерою","manual.f8e60899a881":"<strong>Властивості</strong> пристрою відеозахоплення пропонують <strong>Деінтерлейсинг</strong> для черезрядкових сигналів, як-от з карт захоплення, до яких під'єднано старіші камери й консолі: відкидання, bob, лінійний, змішування чи адаптивний до руху, з порядком полів. Він працює однаково в кожній системі; його зміна перезапускає пристрій.","manual.34192e6d30fd":"<strong>Керування камерою</strong> — експозиція, баланс білого, фокус, зум, підсилення тощо — з'являється в тих самих <strong>Властивостях</strong>, поки камера працює. Windows і Linux використовують стандартні елементи керування UVC; macOS показує те, що повідомляє система, а це часто нічого, і панель так і каже, а не показує повзунки, що нічого не роблять. Кожне налаштування зберігається в <strong>профілі цієї камери</strong> й застосовується знову, коли її знову під'єднують або застосунок перезапускається; <strong>Скинути профіль</strong> повертає типові значення.","manual.f77f10d8c967":"Автоматизація та керування","manual.726216fb4de1":"Нехай студія керує собою сама за допомогою правил, макросів і апаратних контролерів — кожен із них обмежений одним фіксованим списком команд студії, тож жодна автоматизація не може назвати файл, запустити програму чи дістатися інтернету.","manual.193521bd4921":"Правила, макроси й змінні","manual.e8ee7ccab125":"Відкрийте <strong>Інструменти → Правила автоматизації та макроси…</strong> і додайте правило. Виберіть один із дев'яти тригерів (зміна сцени, початок чи зупинка трансляції, початок чи зупинка запису, помилка джерела, перетин рівнем звуку порогу, перехід системи в бездіяльність, отримання фокуса вікном, час доби або зміна відстежуваного файлу), додайте умови (значення змінної, ефір, запис) і виберіть дію студії. Кожне правило спершу <strong>вимкнене</strong>: увімкніть його, щоб воно запрацювало.","manual.5deaa7ba718f":"Створіть макрос як іменований список кроків — виконати дію, зачекати, задати змінну — з кількістю повторів і необов'язковою глобальною гарячою клавішею. Запускайте його із застосунку, гарячою клавішею, правилом або через API віддаленого керування.","manual.30ee5b1326f2":"Задайте в макросі <strong>змінну</strong> студії й використовуйте її як <code>{{name}}</code> у будь-якому джерелі «Текст»: текст змінюється тієї ж миті, коли макрос задає значення.","manual.5eb10fc04538":"Контролери: MIDI, OSC і сенсорна панель","manual.ba0c838f1688":"Відкрийте <strong>Інструменти → MIDI-керування…</strong> й навчіть його пад, ручку чи фейдер для дії, макросу, зміни сцени, фейдера мікшера чи вимкнення звуку — зі світлодіодами й моторизованими фейдерами, що відображають реальний стан студії. Жоден MIDI-порт не відкривається, доки ви його не виберете.","manual.cc993cb0d974":"Увімкніть <strong>Приймати OSC</strong>, щоб контролери на кшталт TouchOSC і світлові пульти могли надсилати адреси, як-от <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> і <code>/mixer/vol</code>. Це вимкнено за замовчуванням і прослуховує лише цей комп'ютер, якщо ви не дозволите свою мережу. OSC не має власного пароля.","manual.134e5f4269f9":"Відкрийте <strong>Інструменти → LAN-панель і tally…</strong>, щоб роздавати сторінку керування — кнопки сцен із живим талі, фейдери мікшера й клавіші дій — на будь-який телефон через QR-код. Кожен запит потребує пароля, і панель прослуховує лише цей комп'ютер, якщо ви не дозволите свою мережу. Сторінка талі показує повноекранний червоний чи зелений; додайте <code>?scene=NAME</code>, щоб стежити за однією сценою.","manual.fc4cd96b860d":"Акорди й шари гарячих клавіш","manual.ec4a9a334753":"У полі гарячої клавіші призначте звичайну комбінацію (Ctrl+Shift+M) або двокроковий акорд (Ctrl+K, потім 3) — друга клавіша займається лише тоді, коли акорд очікує. Задайте прив'язці <strong>Шар</strong>, щоб вона працювала лише тоді, коли цей шар активний; шари лишаються перемкненими, доки ви їх не зміните.","manual.70ad05980925":"Камери та сценарій ефіру","manual.24b33b058b99":"Відкрийте <strong>Інструменти → PTZ-камери…</strong>, додайте камеру за її адресою VISCA-over-IP, збережіть іменовані пресети панорамування, нахилу й зуму та прив'яжіть пресет до сцени, щоб перехід до цієї сцени викликав потрібний план. PTZ лишається у вашій мережі, а камера існує лише тому, що ви ввели її адресу: нічого не шукається.","manual.c9d86b995c5a":"Відкрийте <strong>Інструменти → Показати сценарій ефіру…</strong> і перелічіть кроки — сцену, скільки вона триває, і необов'язкові дії — з ручним або автоматичним переходом, живим показом «далі» й часом, що лишився. Сценарій перемикає сцени звичайним способом, який можна скасувати, і ніколи не редагує вашу колекцію сцен.","manual.5c94bed2d737":"<strong>Примітка:</strong> кожне правило, макрос, прив'язка MIDI чи OSC, кнопка панелі й крок сценарію проходять через той самий фіксований список команд, що й API віддаленого керування, тож жоден контролер не може зробити того, чого не можуть власні кнопки застосунку. Кожен мережевий слухач вимкнено за замовчуванням, і він лишається на цьому комп'ютері, якщо ви не дозволите свою мережу, а налаштування OSC і панелі попереджають, що мережевий трафік не шифрується, перш ніж порт відкриється.","manual.1f3fd1c7ddc9":"Мультистрим","manual.dcac0a03a29b":"Транслюйте на кілька платформ одночасно — прямо зі свого комп'ютера, без проміжного сервісу ретрансляції.","manual.42d9628818da":"Додайте два чи більше напрямки трансляції в <strong>Налаштування → Трансляція</strong> й увімкніть кожен.","manual.4144fe0d9694":"Задайте платформі власні налаштування кодувальника, якщо їй потрібен інший бітрейт.","manual.cb21d6bb96be":"Натисніть <strong>В ефір</strong>: ви транслюєте на всі ввімкнені напрямки одночасно. Панель статистики показує стан і бітрейт кожного напрямку, а збій одного напрямку ніколи не зупиняє решту.","manual.aba9a5f55973":"За бажання водночас записуйте локальну копію з окремими доріжками й зберігайте повтори гарячою клавішею повтору під час трансляції.","manual.af9343c245a7":"<strong>Зараз безкоштовно:</strong> кожна функція — мультистрим, SRT і WHIP, кожен фільтр, скрипти, повтори, набори переходів і API віддаленого керування — сьогодні безкоштовна для всіх. Майбутні версії можуть продаватися.","manual.c08320c45003":"Надійність трансляцій і розуміння","manual.532ab322d03c":"Репетируйте, вимірюйте й пояснюйте свій ефір. Усе тут за замовчуванням вимкнене або нейтральне, і ніщо з цього не виходить у мережу.","manual.80390ae1a9d7":"Симулятор мережі","manual.7e620ced841e":"У <strong>Налаштування → Трансляція</strong> відкрийте <strong>Симулятор мережі (репетиції)</strong> і виберіть <strong>Профіль</strong> — <strong>Готельний Wi-Fi</strong>, <strong>Мобільна точка доступу</strong> або <strong>Власний</strong> із вашими значеннями <strong>Пропускна здатність</strong>, <strong>Затримка</strong>, <strong>Джитер</strong> і запланованими періодами <strong>Обрив</strong>. Він впливає лише на локальний вихід репетиції, тож ви можете тренувати перепідключення, мультистрим і вибір бітрейту; він ніколи не може сповільнити справжню трансляцію.","manual.b22d8c51e0bd":"Режим репетиції","manual.083772633b86":"Натисніть фіолетову кнопку <strong>Репетиція</strong>, щоб запустити весь конвеєр — компонувальник, кодувальник, мультиплексор і справжню логіку перепідключення — у локальну заміну, причому <strong>ніщо не залишає комп'ютер</strong>. Значок <strong>РЕПЕТИЦІЯ</strong> позначає кожен елемент керування ефіром, а ваші ключі трансляції навіть не зчитуються, тож можна репетирувати ще до того, як ви їх отримаєте. Репетицію також можна записати.","manual.184d64047c4c":"<strong>Порада:</strong> поєднайте репетицію із симулятором мережі, щоб задовго до дня ефіру потренувати перепідключення через слабке, нестабільне з'єднання.","manual.d2381a584d24":"Хронологія пропущених кадрів","manual.a6a72c5410a8":"<strong>Часова шкала сесії</strong> записує всю сесію — час рендерингу, чергу кодувальника, бітрейт і пропущені кадри кожного напрямку, перепідключення, зміни сцен, мітки й тривоги — на одному графіку, який можна масштабувати. Якщо панель статистики показує <em>поточний момент</em>, то часова шкала згодом відповідає на питання «що сталося на 43-й хвилині?».","manual.6e9fee1e85fa":"Звіт про сесію й бенчмарк кодувальників","manual.9dd812cbf648":"Увімкніть <strong>Записувати звіт про сесію (HTML + Markdown) поруч із записом</strong> у <strong>Налаштування → Трансляція</strong>, щоб після завершення сесії отримати локальний підсумок: час роботи, середній і піковий бітрейт для кожного напрямку, час простою, перепідключення, мітки, тривоги й розташування запису. Він лишається на вашому комп'ютері й за замовчуванням вимкнений.","manual.a9e574b7bd8d":"Скористайтеся <strong>Запустити бенчмарк кодерів…</strong>, щоб виміряти короткі кодування кожним кодувальником, пресетом і роздільністю, які має ваш комп'ютер, — приблизно хвилина, повністю офлайн, — а потім натисніть <strong>Застосувати до налаштувань запису</strong> в результатах. Невдачі перелічено, а не приховано, і бенчмарк відмовляється запускатися, поки ви в ефірі чи записуєте.","manual.fae310275ed2":"Джерела лише в трансляції або лише в записі","manual.191da176dd0d":"У рядку джерела використовуйте <strong>Показати у стрімі</strong> / <strong>Приховати у стрімі</strong> та <strong>Показати в записі</strong> / <strong>Приховати в записі</strong>, щоб сповіщення й чат були в живій трансляції, а запис лишався чистим, — з одного полотна. Головна кнопка з оком і далі керує всім, а попередній перегляд, проєктори й мультив'ю завжди показують усю програму.","manual.46bad2cb618f":"Віртуальна камера","manual.69ebe5277092":"Використовуйте свою програму як вебкамеру в будь-якому застосунку для відеодзвінків. <strong>У 1.2.1 — лише Windows.</strong>","manual.ba2b6aa952f7":"Натисніть <strong>Запустити віртуальну камеру</strong> на панелі <strong>Керування</strong>. Freally Capture додає системну камеру з назвою <strong>«Freally Capture Virtual Camera»</strong>.","manual.cb3cb4585f19":"У Zoom, Meet, Discord чи Teams виберіть цю камеру в налаштуваннях відео: ваша програма стає вебкамерою.","manual.83db59f4a370":"Натисніть <strong>Зупинити віртуальну камеру</strong>, щоб прибрати її.","manual.91c51d55639b":"<strong>Для кожної системи:</strong> у <strong>Windows</strong> камера реєструється для вашого користувача без прав адміністратора й видаляється, коли ви її зупиняєте. Вона <strong>ще не має цифрового підпису</strong>, тож Windows може попереджати про неї, а захищений застосунок для відеодзвінків може її відхилити; повний тест у живому дзвінку ще попереду. Камери для <strong>macOS</strong> і <strong>Linux</strong> — це окремі компоненти, яких <em>немає в цьому випуску</em>. Freally Capture ніколи не встановлює системний компонент без запиту — в жодній системі.","manual.98839b8e6880":"Джерело-браузер","manual.3ba821584b20":"Розмістіть живу вебсторінку — накладення сповіщень, табло, віджет чату — прямо в сцені.","manual.895f07f428cd":"На панелі <strong>Джерела</strong> натисніть <strong>+</strong> і виберіть <strong>Браузер</strong>.","manual.868ee19e975e":"Вставте адресу <strong>http://</strong> або <strong>https://</strong> і задайте розмір і частоту кадрів, з якими її рендерити.","manual.292e94b0a782":"Під час першого використання Freally Capture запропонує встановити компонент <strong>Середовище виконання браузера</strong>. Його завантажують, коли ви про це попросите, і перевіряють за хешем — він ніколи не постачається разом із застосунком, — і ви можете знову видалити його в <strong>Інструменти → Компоненти</strong>.","manual.cd6d7fbd46ee":"<strong>Завантажуються лише http і https.</strong> Правило охоплює кожну зміну сторінки, а не лише адресу, яку ви вводите: якщо сторінка намагається перейти на <code>file://</code>, <code>javascript:</code> чи <code>data:</code> — через переспрямування, скрипт, спливне вікно чи фрейм, — перехід <strong>скасовується</strong>, тож сторінка не може прочитати ваші файли. У Windows сторінка працює в пісочниці Chromium. Середовище виконання <strong>ще не має цифрового підпису</strong>. Звук сторінки поки не захоплюється: ця версія — лише зображення.","manual.9c0c8f127dd9":"Захоплення ігор","manual.2c08692420b8":"Захоплюйте гру в ексклюзивному повноекранному режимі, якої не бачить звичайне захоплення вікна. <strong>Лише Windows.</strong>","manual.9d162e3861e9":"На панелі <strong>Джерела</strong> натисніть <strong>+</strong> і виберіть <strong>Захоплення гри</strong>. <strong>Спершу прочитайте попередження</strong>: воно простими словами пояснює ризик.","manual.4264b41a7732":"Прийміть ризик <em>для цієї однієї гри</em>, а потім виберіть запущену гру зі списку.","manual.ab3e826e90f1":"Freally Capture завантажує в цю гру невеликий перехоплювач і бере її кадри з власною частотою кадрів гри.","manual.082fd06e18f9":"<strong>Прочитайте це перед використанням.</strong> Захоплення ігор працює через <strong>завантаження DLL у гру</strong>. Античит і антивірусне ПЗ можуть розцінити це як втручання, і обліковий запис можуть <strong>заблокувати</strong>. Нічого ніколи не завантажується автоматично: ви погоджуєтеся <strong>для однієї гри за раз</strong>, і цю згоду ніколи не можна використати для іншої гри — і вона ніколи не переноситься всередині спільної колекції сцен. Якщо гра відхиляє перехоплювач, Freally Capture переходить на звичайне <strong>Захоплення вікна</strong> з повідомленням, а не завершується невдачею. Ігри з HDR та ігри на Direct3D 12 теж використовують захоплення вікна. У macOS і Linux це джерело не пропонується.","manual.43fae75af922":"Буфер повторів","manual.40bc664c1c0b":"Тримайте останні миті в пам'яті, щоб гаряча клавіша зберігала те, що щойно сталося.","manual.7a69241c10c2":"Натисніть <strong>Запустити буфер повторів</strong> на панелі <strong>Керування</strong>. Freally Capture зберігає останні секунди в буфері фіксованого розміру.","manual.684aecea2ba0":"Призначте глобальну гарячу клавішу <strong>Зберегти повтор</strong> у <strong>Налаштуваннях</strong>.","manual.66c44777e965":"Натисніть її, щоб зберегти останні секунди у файл, — не перериваючи ні трансляції, ні основного запису. Повідомлення «Повтор збережено» це підтверджує.","manual.4b598d5daf11":"Телесуфлер","manual.b7fc474ded62":"Плавно прокручуваний текст для людини в кадрі — на панелі в застосунку, на повноекранному проєкторі, який можна віддзеркалити, і на сенсорній панелі в локальній мережі, усе одночасно.","manual.f1c548f77750":"Відкрийте телесуфлер з меню <strong>Інструменти</strong>, введіть або вставте текст і задайте швидкість і шрифт. Задавайте темп у <strong>символах за секунду</strong> або перемкніться на <strong>BPM</strong> (50–250 ударів за хвилину), щоб читати текст пісні в такт музиці; будь-яка з цих змін підлаштовує темп прокручування, що вже йде.","manual.3a86eb91938d":"<strong>Чипи пауз:</strong> введіть <code> -- </code> для короткої паузи або <code> --N </code> для утримання на N секунд, і це стане одним чипом — курсор переступає через нього, одне натискання Delete чи Backspace його видаляє, а копіювання й вставлення зберігають його цілим.","manual.dc7539148aed":"<strong>Почати зворотний відлік:</strong> увімкніть необов'язковий вступний відлік 3-2-1, що показується і в попередньому перегляді оператора, і на проєкторі, щоб у читача була мить, перш ніж текст рушить.","manual.f5113c573ac4":"<strong>Відкрийте проєктор</strong> для читача (режим дзеркала перевертає його для скла світлодільника). Його відкриття закриває вікно оператора, тож ви можете вести трансляцію з головного вікна, поки людина читає; якщо ввімкнено зворотний відлік, проєктор повертається на початок, відлічує й запускає прокручування. Відтворюйте, ставте на паузу, зупиняйте, перемотуйте назад і вперед та перезапускайте за допомогою екранних кнопок, гарячої клавіші, MIDI, OSC чи LAN-панелі — усі елементи керування лишаються синхронними.","manual.5298a60b0152":"<strong>Читати вголос</strong> програє текст власним мовленням вашої системи: вбудованими голосами Windows чи macOS, а в Linux — <code>spd-say</code> або <code>espeak-ng</code>, якщо вони встановлені. Жоден рушій мовлення не постачається в комплекті.","manual.5de1b5efa245":"<strong>Автодоповнення</strong> пропонує слова й фрази світло-сірим під час введення; натисніть Tab, щоб прийняти. Кожна з 18 мов має власний словник на вашому комп'ютері, який завантажується лише для мови, якою ви пишете.","manual.7fb5d22a1670":"Віддалене керування","manual.b2ba73efdcec":"Керуйте студією зі Stream Deck чи контролера на кшталт Companion — вимкнено за замовчуванням, захищено паролем, на вашому власному комп'ютері.","manual.6396674fcd28":"Відкрийте <strong>Налаштування → Віддалене керування</strong>, увімкніть <strong>WebSocket API</strong> (вимкнено за замовчуванням) і задайте <strong>Пароль</strong>.","manual.56e0d6d295bb":"Він прослуховує <code>127.0.0.1</code> — лише цей комп'ютер, — якщо ви явно не дозволите свою мережу.","manual.344e52e3eba1":"Спрямуйте клієнт Companion чи Stream Deck на показану адресу. Перемикайте сцени, запускайте переходи, вимикайте й вмикайте звук, починайте й зупиняйте запис і зберігайте повтори апаратними кнопками.","manual.6664edd9ad4c":"Віддалені гості та виробництво ефіру","manual.75ce17238f9b":"Перетворіть сесію з віддаленими гостями на повноцінне шоу: до восьми гостей, малювання поверх живої програми, кімната очікування, особисті сигнали, зв'язок кожного гостя з першого погляду й автоматична сітка. Усе тут за замовчуванням вимкнене або не прив'язане, і нічого не підключається, доки ви когось не запросите.","manual.02d9e34002c8":"Сесії з кількома гостями","manual.5a6c2ec7640d":"Почніть сесію з віддаленими гостями й поділіться посиланням-запрошенням або його QR-кодом: <strong>ви плюс до восьми гостей</strong>, галерея від одного до дев'яти. Кожен гість — це плитка з власними кнопками вимкнення звуку, якістю з'єднання, каналом сигналів і виведенням в ефір одним клацанням.","manual.34a323a45540":"Гість відкриває посилання у веббраузері — нічого не треба встановлювати — і натискає <strong>Приєднатися</strong>, щоб надіслати свої камеру й мікрофон. Гість, у якого є Freally Capture, може натомість відкрити те саме запрошення в застосунку. Запрошення спливає після вибраного вами часу.","manual.4e31042e4a6f":"<strong>Примітка:</strong> зображення й звук ідуть напряму між вами й кожним гостем, однорангово й у зашифрованому вигляді під час передачі; лише встановлення з'єднання проходить через публічний сервіс сигналізації. Сесії перевірено з чотирма гостями; більше залежить від вашої пропускної здатності й процесора.","manual.33ff43cd0616":"Телестратор: малювання поверх живої програми","manual.d29f651d6eb9":"Відкрийте <strong>Телестратор</strong> і виберіть інструмент — <strong>Ручка</strong>, <strong>Маркер</strong>, <strong>Стрілка</strong> або <strong>Еліпс</strong>, — а потім малюйте прямо на програмі. Ваші позначки стають частиною зображення тієї ж миті, коли ви їх малюєте, тож вони з'являються в записі й трансляції, а не лише у вашому попередньому перегляді.","manual.9aa7fc0273fb":"Увімкніть <strong>Згасання</strong>, щоб позначки зникали через деякий час, або перемкніться в <strong>Режим дошки</strong>, щоб <strong>Залишити</strong> їх, доки ви їх не очистите. Малювання враховує тиск пера планшета, а <strong>Очистити позначки</strong> можна призначити на гарячу клавішу (за замовчуванням не призначено).","manual.fc81cd8d37ae":"Кімната очікування","manual.c87beb96ec64":"Увімкніть <strong>Кімнату очікування</strong>, і нові гості чекатимуть поза ефіром, поки ви перевіряєте їхні камеру й мікрофон у <strong>Перегляді кімнати очікування</strong>. Коли вони готові, натисніть <strong>Вивести в ефір</strong>. Гість бачить банер «ви в кімнаті очікування» — у застосунку чи на вебсторінці.","manual.1d47c8224f50":"Сигнали й розмова","manual.569d461035c1":"Надішліть гостю особистий <strong>Сигнал</strong> — з пресетами, як-от <strong>30 секунд</strong>, <strong>Завершуйте</strong>, <strong>Ви наступний</strong> і <strong>Говоріть гучніше</strong>, — через наявний одноранговий канал сесії. Гість бачить його з живим зворотним відліком, і він ніколи не потрапляє в програму.","manual.c66c9d5359bf":"Панель якості з'єднання","manual.4541cc1ee0f5":"Стежте за з'єднанням кожного гостя наживо — час двобічної передачі, втрата пакетів, роздільність і частота кадрів, які ви отримуєте, і джитер — із зеленим, бурштиновим чи червоним значком і невеликим графіком історії, щоб погіршення з'єднання було видно раніше, ніж його помітять глядачі.","manual.bf8e764221e5":"Автоматичні сітки гостей","manual.ffe3c227cdfc":"Увімкніть <strong>Автосітка</strong>, щоб гості в ефірі трималися в охайній сітці від одного до дев'яти, яка сама перебудовується, коли гості приєднуються, виходять чи виводяться в ефір, або натисніть кнопку впорядкування, щоб зробити це зараз. Кожне місце публікує ім'я свого гостя як змінну <code>{{guestN}}</code>, тож джерело титру стає табличкою з іменем, що оновлюється сама.","manual.e8630fabd4e5":"Керування студією та робочий процес","manual.c8c487196725":"Зробіть цілу розкладку переносною й такою, якою можна поділитися, зберігайте іменовані версії своїх сцен, змінюйте тему застосунку й тримайте улюблені дії на відстані одного дотику — усе на вашому комп'ютері, без сервера.","manual.f87995a7cf6c":"Пакунки сцен і версії","manual.074bb2bf9453":"Відкрийте діалог робочого простору через <strong>Колекція сцен → Керування колекціями сцен…</strong>: там є всі інструменти для пакунків, порівняння, знімків, резервних копій і макетів панелей.","manual.8dce3a052a05":"Натисніть <strong>Експортувати пакунок…</strong>, щоб зібрати поточну колекцію та її файли (зображення, медіа, LUT, маски, шрифти) в один переносний <code>.fcappack</code>. Вебадреси й мережеві шляхи позначаються як <em>зовнішні</em>, а не включаються в пакунок, а шрифти позначаються з огляду на їхні ліцензії.","manual.c1bba88df9c5":"Натисніть <strong>Імпортувати пакунок…</strong> і виберіть <code>.fcappack</code>: він з'являється як нова колекція, знаходить свої файли на цьому комп'ютері, і застосунок перемикається на неї.","manual.69e7b9f6e8ab":"Натисніть <strong>Порівняти та об’єднати…</strong>, щоб порівняти поточну колекцію з іншою колекцією, пакунком чи знімком. Перегляньте додані, вилучені й змінені сцени, джерела, трансформації, фільтри й видимість, а потім виберіть, які саме зміни перенести. Вибір сцени переносить і джерела, які вона використовує.","manual.862a75c84629":"Натисніть <strong>Знімки…</strong>, назвіть контрольну точку й виберіть <strong>Зберегти знімок</strong>. <strong>Відновити</strong> повертає її пізніше — ваша поточна розкладка спершу зберігається як знімок, тож відновлення ніколи не буває безповоротним. Зберігається до 50 знімків, і показано, скільки місця на диску вони займають.","manual.8058b1480d14":"<strong>Порада:</strong> знімки — це іменована історія поряд з автозбереженням і скасуванням. Зробіть знімок перед ризикованою зміною, і у вас завжди буде підписана точка, до якої можна повернутися.","manual.1d55a62a5fdf":"Резервне копіювання, відновлення й портативний режим","manual.250b89a976de":"У діалозі робочого простору натисніть <strong>Резервна копія та відновлення…</strong>, а потім <strong>Експортувати резервну копію…</strong>, щоб зберегти все — налаштування, профілі й колекції сцен — в одному файлі <code>.fcapbackup</code>.","manual.560e7e269f11":"На новому комп'ютері натисніть <strong>Відновити з резервної копії…</strong>, позначте, що перенести (<strong>Налаштування</strong>, <strong>Колекції сцен</strong>, <strong>Профілі</strong>), і виберіть <strong>Відновити вибране</strong>. Потім перезапустіть Freally Capture, щоб завантажити відновлені колекції й профілі.","manual.5b26da4b8793":"Щоб запускати з USB-накопичувача, покладіть поряд із програмою файл <code>freally-portable.txt</code>: тоді всі її дані зберігатимуться в теці програми, а не у вашому профілі користувача. <strong>Налаштування → Про застосунок</strong> показує, чи ввімкнено портативний режим і де лежать дані.","manual.a31a49d41d7d":"<strong>Примітка:</strong> ключі трансляції й паролі ніколи не записуються в резервну копію — введіть їх знову після відновлення.","manual.5b446c4ea972":"Теми, макети й швидкі дії","manual.8eea476bde73":"Відкрийте <strong>Налаштування → Вигляд</strong> і виберіть тему <strong>Власна</strong>, щоб редагувати палітру з живими <strong>попередженнями про контраст</strong>, а потім скористайтеся <strong>Експорт .fctheme…</strong> або <strong>Імпорт .fctheme…</strong>, щоб поділитися нею.","manual.7cc0bc3a4e74":"У розділі <strong>Макети панелей</strong> діалогу робочого простору збережіть поточне розташування під певною назвою й клацніть збережений макет, щоб перемкнутися на нього.","manual.c9044c09b979":"У <strong>Налаштуваннях</strong> введіть запит у <strong>Пошук налаштувань…</strong>, щоб перейти до будь-якого налаштування; позначка показує, які категорії ви змінили, відколи відкрили вікно.","manual.a4640858ad4d":"Виберіть <strong>Інструменти → Швидкі дії…</strong>, щоб відкрити сітку кнопок. Натисніть <strong>Редагувати</strong>, потім <strong>Додати кнопку</strong>, задайте для кожної кнопки підпис і колір і додайте <strong>сторінки</strong>. Кнопка може перемкнути сцену, запустити макрос, відтворити пад саундборду або виконати команду студії.","manual.74ff6472576d":"<strong>Порада:</strong> кнопки швидких дій виконують ті самі команди студії, що й гарячі клавіші, а сітка спільна із сенсорною панеллю в локальній мережі: налаштуйте її один раз — і вона буде й на вашому телефоні.","manual.74a883a037bc":"Налаштування","manual.5feaf4600834":"Профілі, колекції сцен, гарячі клавіші й мова. Усе зараз безкоштовне, тож активувати нічого не потрібно. <strong>Налаштування</strong> — це одне вікно з категоріями «Загальні», «Вигляд», «Трансляція», «Вивід», «Повтор», «Гарячі клавіші», «Мережа», «Доступність» і «Про застосунок», яке відкривається з <strong>рядка меню</strong> («Файл», «Редагування», «Перегляд», «Панелі», «Профіль», «Колекція сцен», «Інструменти» й «Довідка»).","manual.9f6a04e85e39":"<strong>«Застосувати» означає застосувати.</strong> Вікно налаштувань редагує копію: нічого не змінюється, доки ви не натиснете <strong>Застосувати</strong> або <strong>OK</strong>, а <strong>Скасувати</strong> повертає точно те, що було, разом із попереднім переглядом теми.","manual.3fc0968ef6f9":"<strong>Профілі й колекції сцен:</strong> тримайте окремі конфігурації — скажімо, «Трансляція» і «Локальний запис» — і перемикайтеся між ними без перезапуску з меню <strong>Профіль</strong> і <strong>Колекція сцен</strong>.","manual.ce6f52861bdb":"<strong>Гарячі клавіші:</strong> призначайте кожну дію зі списку, у якому не буває конфліктів, — виберіть комбінацію для однієї дії, і вона зникне зі списків усіх інших дій, тож дві функції ніколи не ділять одну клавішу. <strong>Немає</strong> знову її звільняє.","manual.be52349f05be":"<strong>Доступність:</strong> виберіть кольори індикаторів мікшера, зокрема набір, безпечний для людей із порушеннями кольорового зору. Увесь застосунок працює з клавіатури, а програми зчитування з екрана оголошують вихід в ефір, запис, перепідключення й пропущені кадри.","manual.a79c94673558":"<strong>Мова:</strong> виберіть одну з 18 мов; застосунок змінюється одразу, а арабська читається справа наліво.","manual.59274c49ac87":"Як повідомити про проблему","manual.c02ed8aec89d":"Ви вирішуєте, чи потрапить проблема до розробника, і бачите, що саме буде надіслано.","manual.4ed327c34aeb":"Коли застосунок показує помилку, яку спричинив сам, поряд із нею з'являється кнопка <strong>Повідомити</strong>.","manual.95da4b53fdcc":"Після збою наступний запуск пропонує <strong>Повідомити</strong> або <strong>Відхилити</strong>.","manual.6207904599f4":"<strong>Повідомити</strong> відкриває у вашому браузері сторінку звіту Freally Capture на цьому сайті з уже заповненими технічними даними: ви можете їх прочитати, але не змінити. Додайте, що ви робили, і, якщо хочете, адресу електронної пошти. Нічого не надсилається, доки ви не натиснете там <strong>Надіслати</strong>.","manual.6acd4e789ccd":"Ніщо ніколи не надсилається у фоні, а <strong>Відхилити</strong> взагалі нічого не надсилає.","manual.69bd78234ffb":"Приватність і мережа","manual.42f9b04c2640":"Freally Capture не має облікового запису й телеметрії, і в нас немає хмарного сервісу. Ось що саме виходить у мережу, а що — ні.","manual.81fe73d241a8":"<strong>Жодного облікового запису, жодної телеметрії.</strong> Застосунок ніколи не просить вас увійти й ніколи нікуди не надсилає ваші сцени, записи чи будь-які дані про використання.","manual.3735a28566e9":"<strong>Ваша трансляція йде прямо на платформу.</strong> Вона передається з вашого комп'ютера до налаштованих вами сервісів — нашого сервера ретрансляції немає.","manual.512b8fa00684":"<strong>Ваші записи лишаються на вашому комп'ютері,</strong> у вибраній вами теці. Нічого не вивантажується.","manual.c299fcfa1fde":"<strong>Ваші ключі трансляції лишаються на вашому комп'ютері,</strong> відображаються замаскованими й надсилаються лише сервісу, на який ви транслюєте.","manual.414a08bd0219":"<strong>Віддалені гості підключаються напряму між учасниками.</strong> Лише встановлення з'єднання сесії проходить через публічний сервіс сигналізації, і лише тоді, коли ви починаєте сесію.","manual.20c95c4687b3":"<strong>Накладення чату читає публічний чат</strong> каналу, на який ви його спрямували, так само, як глядач без входу в обліковий запис, — без облікового запису, ключа чи входу.","manual.efe87d55bed1":"<strong>Два компоненти завантажуються лише тоді, коли вперше знадобляться:</strong> ffmpeg — для кодеків, яких вимагають платформи, і середовище виконання браузера — для джерела-браузера. Кожен надходить від власного видавця й перевіряється перед використанням.","manual.3601a272b3b0":"<strong>Перевірка оновлень</strong> завантажує один невеликий файл один раз під час кожного запуску, а також коли ви вибираєте <strong>Перевірити оновлення…</strong>. Разом із нею не надсилається нічого про вас чи ваш комп'ютер, і нічого не встановлюється, якщо ви не погодитеся.","manual.11abc96d8e21":"<strong>Звіт про проблему надсилається, лише коли ви натиснете «Надіслати»</strong> на сторінці звіту, після того як прочитаєте його вміст (див. <a href=\"#report\">Як повідомити про проблему</a>).","manual.804fa6536d40":"<strong>Жодного ШІ.</strong> Кожен фільтр — шумозаглушення, хромакей, тональне перетворення — це класична обробка сигналу. Застосунок не містить жодної моделі машинного навчання й жодної не завантажує."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
